class ParquetMetadataConverterFromParquetMetadataTests {

  private final ParquetMetadataConverter converter = new ParquetMetadataConverter();

  @Test
  void convertsPlaintextFileMetadataAndColumnDetails() throws IOException {
    ColumnMetaData idMeta = columnMetaData(Type.INT32, "id", 4L, 10L, 100L, 80L);
    idMeta.setDictionary_page_offset(2L);
    idMeta.setBloom_filter_offset(3000L);
    idMeta.setBloom_filter_length(64);
    ColumnChunk idChunk = new ColumnChunk(4L)
        .setFile_path("part-0.parquet")
        .setMeta_data(idMeta)
        .setColumn_index_offset(1000L)
        .setColumn_index_length(16)
        .setOffset_index_offset(2000L)
        .setOffset_index_length(32);

    ColumnChunk nameChunk = new ColumnChunk(204L)
        .setFile_path("part-0.parquet")
        .setMeta_data(columnMetaData(Type.BINARY, "name", 204L, 20L, 200L, 160L));

    RowGroup rowGroup = new RowGroup(Arrays.asList(idChunk, nameChunk), 500L, 50L).setOrdinal((short) 4);
    FileMetaData fileMetadata = new FileMetaData(1, twoColumnSchema(), 50L, Collections.singletonList(rowGroup));
    fileMetadata.setCreated_by("parquet-mr version 1.13.0");
    fileMetadata.setKey_value_metadata(Arrays.asList(
        new KeyValue("writer").setValue("test"), new KeyValue("purpose").setValue("metadata conversion")));

    Map<RowGroup, Long> rowGroupOffsets = new HashMap<>();
    rowGroupOffsets.put(rowGroup, 700L);

    ParquetMetadata result = converter.fromParquetMetadata(fileMetadata, null, false, rowGroupOffsets);

    org.apache.parquet.hadoop.metadata.FileMetaData resultFileMetadata = result.getFileMetaData();
    assertEquals("schema", resultFileMetadata.getSchema().getName());
    assertEquals(2, resultFileMetadata.getSchema().getFieldCount());
    assertEquals(
        PrimitiveTypeName.INT32,
        resultFileMetadata.getSchema().getType("id").asPrimitiveType().getPrimitiveTypeName());
    assertEquals(
        Repetition.OPTIONAL,
        resultFileMetadata.getSchema().getType("name").getRepetition());
    assertEquals("parquet-mr version 1.13.0", resultFileMetadata.getCreatedBy());
    assertEquals(EncryptionType.UNENCRYPTED, resultFileMetadata.getEncryptionType());
    assertEquals("test", resultFileMetadata.getKeyValueMetaData().get("writer"));
    assertEquals("metadata conversion", resultFileMetadata.getKeyValueMetaData().get("purpose"));
    assertNull(resultFileMetadata.getFileDecryptor());

    assertEquals(1, result.getBlocks().size());
    BlockMetaData block = result.getBlocks().get(0);
    assertEquals(50L, block.getRowCount());
    assertEquals(500L, block.getTotalByteSize());
    assertEquals("part-0.parquet", block.getPath());
    assertEquals(4, block.getOrdinal());
    assertEquals(700L, block.getRowIndexOffset());
    assertEquals(2, block.getColumns().size());

    ColumnChunkMetaData idColumn = block.getColumns().get(0);
    assertEquals(ColumnPath.get("id"), idColumn.getPath());
    assertEquals(PrimitiveTypeName.INT32, idColumn.getPrimitiveType().getPrimitiveTypeName());
    assertEquals(CompressionCodecName.UNCOMPRESSED, idColumn.getCodec());
    assertEquals(4L, idColumn.getFirstDataPageOffset());
    assertEquals(2L, idColumn.getDictionaryPageOffset());
    assertEquals(10L, idColumn.getValueCount());
    assertEquals(100L, idColumn.getTotalUncompressedSize());
    assertEquals(80L, idColumn.getTotalSize());
    assertEquals(4, idColumn.getRowGroupOrdinal());
    assertEquals(3000L, idColumn.getBloomFilterOffset());
    assertEquals(64, idColumn.getBloomFilterLength());

    IndexReference columnIndex = idColumn.getColumnIndexReference();
    assertNotNull(columnIndex);
    assertEquals(1000L, columnIndex.getOffset());
    assertEquals(16, columnIndex.getLength());
    IndexReference offsetIndex = idColumn.getOffsetIndexReference();
    assertNotNull(offsetIndex);
    assertEquals(2000L, offsetIndex.getOffset());
    assertEquals(32, offsetIndex.getLength());

    ColumnChunkMetaData nameColumn = block.getColumns().get(1);
    assertEquals(ColumnPath.get("name"), nameColumn.getPath());
    assertEquals(PrimitiveTypeName.BINARY, nameColumn.getPrimitiveType().getPrimitiveTypeName());
    assertEquals(20L, nameColumn.getValueCount());
    assertEquals(4, nameColumn.getRowGroupOrdinal());
    assertEquals(-1L, nameColumn.getBloomFilterOffset());
    assertEquals(-1, nameColumn.getBloomFilterLength());
    assertNull(nameColumn.getColumnIndexReference());
    assertNull(nameColumn.getOffsetIndexReference());
  }

  @Test
  void appliesRowIndexOffsetsOnlyToMappedRowGroupsAndPreservesOptionalOrdinals() throws IOException {
    RowGroup mappedRowGroup = new RowGroup(
            Collections.singletonList(columnChunk(Type.INT32, "id", "data.parquet", 4L)), 100L, 10L)
        .setOrdinal((short) 7);
    RowGroup unmappedRowGroup = new RowGroup(
            Collections.singletonList(columnChunk(Type.INT32, "id", "data.parquet", 104L)), 120L, 20L);
    FileMetaData fileMetadata = new FileMetaData(
        1, twoColumnSchema(), 30L, Arrays.asList(mappedRowGroup, unmappedRowGroup));

    Map<RowGroup, Long> rowGroupOffsets = new HashMap<>();
    rowGroupOffsets.put(mappedRowGroup, 1234L);

    ParquetMetadata result = converter.fromParquetMetadata(fileMetadata, null, false, rowGroupOffsets);

    assertEquals(2, result.getBlocks().size());
    BlockMetaData first = result.getBlocks().get(0);
    assertEquals(1234L, first.getRowIndexOffset());
    assertEquals(7, first.getOrdinal());
    assertEquals(7, first.getColumns().get(0).getRowGroupOrdinal());

    BlockMetaData second = result.getBlocks().get(1);
    assertEquals(-1L, second.getRowIndexOffset());
    assertEquals(0, second.getOrdinal());
    assertEquals(0, second.getColumns().get(0).getRowGroupOrdinal());
  }

  @Test
  void acceptsNullAndEmptyRowGroupLists() throws IOException {
    FileMetaData nullRowGroups = new FileMetaData(1, twoColumnSchema(), 0L, null);
    ParquetMetadata nullResult = converter.fromParquetMetadata(
        nullRowGroups, null, false, Collections.emptyMap());
    assertTrue(nullResult.getBlocks().isEmpty());
    assertEquals("schema", nullResult.getFileMetaData().getSchema().getName());

    FileMetaData emptyRowGroups =
        new FileMetaData(1, twoColumnSchema(), 0L, Collections.emptyList());
    ParquetMetadata emptyResult = converter.fromParquetMetadata(
        emptyRowGroups, null, false, Collections.emptyMap());
    assertTrue(emptyResult.getBlocks().isEmpty());
  }

  @Test
  void rejectsColumnChunksThatReferenceDifferentFiles() {
    ColumnChunk first = new ColumnChunk(4L)
        .setFile_path("part-0.parquet")
        .setMeta_data(columnMetaData(Type.INT32, "id", 4L, 10L, 100L, 80L));
    ColumnChunk second = new ColumnChunk(104L)
        .setFile_path("part-1.parquet")
        .setMeta_data(columnMetaData(Type.BINARY, "name", 104L, 10L, 100L, 80L));
    RowGroup rowGroup = new RowGroup(Arrays.asList(first, second), 200L, 10L);
    FileMetaData fileMetadata =
        new FileMetaData(1, twoColumnSchema(), 10L, Collections.singletonList(rowGroup));

    ParquetDecodingException exception = assertThrows(
        ParquetDecodingException.class,
        () -> converter.fromParquetMetadata(fileMetadata, null, false, Collections.emptyMap()));

    assertEquals(
        "all column chunks of the same row group must be in the same file for now",
        exception.getMessage());
  }

  @Test
  void rejectsNullFirstFilePathWhenAnotherColumnHasAFilePath() {
    ColumnChunk first = new ColumnChunk(4L)
        .setMeta_data(columnMetaData(Type.INT32, "id", 4L, 10L, 100L, 80L));
    ColumnChunk second = new ColumnChunk(104L)
        .setFile_path("part-0.parquet")
        .setMeta_data(columnMetaData(Type.BINARY, "name", 104L, 10L, 100L, 80L));
    RowGroup rowGroup = new RowGroup(Arrays.asList(first, second), 200L, 10L);
    FileMetaData fileMetadata =
        new FileMetaData(1, twoColumnSchema(), 10L, Collections.singletonList(rowGroup));

    assertThrows(
        ParquetDecodingException.class,
        () -> converter.fromParquetMetadata(fileMetadata, null, false, Collections.emptyMap()));
  }

  @Test
  void fallsBackWhenCreatedByCannotBeParsedAsAWriterVersion() throws IOException {
    RowGroup rowGroup = new RowGroup(
        Collections.singletonList(columnChunk(Type.INT32, "id", null, 4L)), 100L, 10L);
    FileMetaData fileMetadata =
        new FileMetaData(1, twoColumnSchema(), 10L, Collections.singletonList(rowGroup));
    fileMetadata.setCreated_by("not a recognizable writer version");

    ParquetMetadata result = converter.fromParquetMetadata(
        fileMetadata, null, false, Collections.emptyMap());

    assertEquals("not a recognizable writer version", result.getFileMetaData().getCreatedBy());
    assertEquals(1, result.getBlocks().size());
    assertEquals(ColumnPath.get("id"), result.getBlocks().get(0).getColumns().get(0).getPath());
    assertNull(result.getBlocks().get(0).getPath());
  }

  @Test
  void reportsPlaintextFooterEncryptionTypeWhenEncryptionAlgorithmIsPresent() throws IOException {
    FileMetaData fileMetadata = new FileMetaData(1, twoColumnSchema(), 0L, Collections.emptyList());
    fileMetadata.setEncryption_algorithm(EncryptionAlgorithm.AES_GCM_V1(new AesGcmV1()));

    ParquetMetadata result = converter.fromParquetMetadata(
        fileMetadata, null, false, Collections.emptyMap());

    assertEquals(EncryptionType.PLAINTEXT_FOOTER, result.getFileMetaData().getEncryptionType());
    assertTrue(result.getBlocks().isEmpty());
  }

  @Test
  void reportsEncryptedFooterEncryptionTypeFromArgument() throws IOException {
    FileMetaData fileMetadata = new FileMetaData(1, twoColumnSchema(), 0L, Collections.emptyList());

    ParquetMetadata result = converter.fromParquetMetadata(
