  void marksEachPlaintextColumnInEncryptedFileDecryptor() throws IOException {
    InternalFileDecryptor decryptor = mock(InternalFileDecryptor.class);
    when(decryptor.plaintextFile()).thenReturn(false);
    RowGroup rowGroup = new RowGroup(
        Arrays.asList(
            columnChunk(Type.INT32, "id", "data.parquet", 4L),
            columnChunk(Type.BINARY, "name", "data.parquet", 104L)),
        200L,
        10L);
    FileMetaData fileMetadata =
        new FileMetaData(1, twoColumnSchema(), 10L, Collections.singletonList(rowGroup));

    ParquetMetadata result = converter.fromParquetMetadata(
        fileMetadata, decryptor, false, Collections.emptyMap());

    assertEquals(2, result.getBlocks().get(0).getColumns().size());
    verify(decryptor)
        .setColumnCryptoMetadata(ColumnPath.get("id"), false, false, (byte[]) null, 0);
    verify(decryptor)
        .setColumnCryptoMetadata(ColumnPath.get("name"), false, false, (byte[]) null, 1);
  }

  @Test
  void rejectsFooterKeyEncryptedColumnWhenNoDecryptorIsAvailable() {
    ColumnChunk encryptedColumn = new ColumnChunk(4L)
        .setMeta_data(columnMetaData(Type.INT32, "id", 4L, 10L, 100L, 80L))
        .setCrypto_metadata(ColumnCryptoMetaData.ENCRYPTION_WITH_FOOTER_KEY(
            new EncryptionWithFooterKey()));
    RowGroup rowGroup =
        new RowGroup(Collections.singletonList(encryptedColumn), 100L, 10L);
    FileMetaData fileMetadata =
        new FileMetaData(1, twoColumnSchema(), 10L, Collections.singletonList(rowGroup));

    ParquetCryptoRuntimeException exception = assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> converter.fromParquetMetadata(fileMetadata, null, false, Collections.emptyMap()));

    assertEquals("Column encrypted with footer key: No keys available", exception.getMessage());
  }

  @Test
  void rejectsFooterKeyEncryptedColumnWithoutColumnMetadata() {
    InternalFileDecryptor decryptor = mock(InternalFileDecryptor.class);
    ColumnChunk encryptedColumn = new ColumnChunk(4L)
        .setCrypto_metadata(ColumnCryptoMetaData.ENCRYPTION_WITH_FOOTER_KEY(
            new EncryptionWithFooterKey()));
    RowGroup rowGroup =
        new RowGroup(Collections.singletonList(encryptedColumn), 100L, 10L);
    FileMetaData fileMetadata =
        new FileMetaData(1, twoColumnSchema(), 10L, Collections.singletonList(rowGroup));

    ParquetCryptoRuntimeException exception = assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> converter.fromParquetMetadata(fileMetadata, decryptor, true, Collections.emptyMap()));

    assertEquals("ColumnMetaData not set in Encryption with Footer key", exception.getMessage());
  }

  private static List<SchemaElement> twoColumnSchema() {
    return Arrays.asList(
        new SchemaElement("schema").setNum_children(2),
        new SchemaElement("id")
            .setType(Type.INT32)
            .setRepetition_type(FieldRepetitionType.REQUIRED),
        new SchemaElement("name")
            .setType(Type.BINARY)
            .setRepetition_type(FieldRepetitionType.OPTIONAL));
  }

  private static ColumnMetaData columnMetaData(
