    BlockMetaData block = result.getBlocks().get(0);
    assertEquals(50L, block.getRowCount());
    assertEquals(500L, block.getTotalByteSize());
    assertEquals("part-0.parquet", block.getPath());
    assertEquals(4, block.getOrdinal());
    assertEquals(700L, block.getRowIndexOffset());
    assertEquals(2, block.getColumns().size());

    ColumnChunkMetaData idColumn = block.getColumns().get(0);
    assertEquals(ColumnPath.get("id"), idColumn.getPath());
    assertEquals(PrimitiveTypeName.INT32, idColumn.getPrimitiveType().getPrimitiveTypeName());
    assertEquals(CompressionCodecName.UNCOMPRESSED, idColumn.getCodec());
    assertEquals(4L, idColumn.getFirstDataPageOffset());
    assertEquals(2L, idColumn.getDictionaryPageOffset());
    assertEquals(10L, idColumn.getValueCount());
    assertEquals(100L, idColumn.getTotalUncompressedSize());
    assertEquals(80L, idColumn.getTotalSize());
    assertEquals(4, idColumn.getRowGroupOrdinal());
    assertEquals(3000L, idColumn.getBloomFilterOffset());
    assertEquals(64, idColumn.getBloomFilterLength());

    IndexReference columnIndex = idColumn.getColumnIndexReference();
    assertNotNull(columnIndex);
    assertEquals(1000L, columnIndex.getOffset());
    assertEquals(16, columnIndex.getLength());
    IndexReference offsetIndex = idColumn.getOffsetIndexReference();
    assertNotNull(offsetIndex);
    assertEquals(2000L, offsetIndex.getOffset());
    assertEquals(32, offsetIndex.getLength());

    ColumnChunkMetaData nameColumn = block.getColumns().get(1);
    assertEquals(ColumnPath.get("name"), nameColumn.getPath());
    assertEquals(PrimitiveTypeName.BINARY, nameColumn.getPrimitiveType().getPrimitiveTypeName());
    assertEquals(20L, nameColumn.getValueCount());
    assertEquals(4, nameColumn.getRowGroupOrdinal());
    assertEquals(-1L, nameColumn.getBloomFilterOffset());
    assertEquals(-1, nameColumn.getBloomFilterLength());
    assertNull(nameColumn.getColumnIndexReference());
    assertNull(nameColumn.getOffsetIndexReference());
  }

  @Test
  void appliesRowIndexOffsetsOnlyToMappedRowGroupsAndPreservesOptionalOrdinals() throws IOException {
    RowGroup mappedRowGroup = new RowGroup(
            Collections.singletonList(columnChunk(Type.INT32, "id", "data.parquet", 4L)), 100L, 10L)
        .setOrdinal((short) 7);
    RowGroup unmappedRowGroup = new RowGroup(
            Collections.singletonList(columnChunk(Type.INT32, "id", "data.parquet", 104L)), 120L, 20L);
    FileMetaData fileMetadata = new FileMetaData(
        1, twoColumnSchema(), 30L, Arrays.asList(mappedRowGroup, unmappedRowGroup));

    Map<RowGroup, Long> rowGroupOffsets = new HashMap<>();
    rowGroupOffsets.put(mappedRowGroup, 1234L);

    ParquetMetadata result = converter.fromParquetMetadata(fileMetadata, null, false, rowGroupOffsets);

    assertEquals(2, result.getBlocks().size());
    BlockMetaData first = result.getBlocks().get(0);
    assertEquals(1234L, first.getRowIndexOffset());
    assertEquals(7, first.getOrdinal());
    assertEquals(7, first.getColumns().get(0).getRowGroupOrdinal());

    BlockMetaData second = result.getBlocks().get(1);
    assertEquals(-1L, second.getRowIndexOffset());
    assertEquals(0, second.getOrdinal());
    assertEquals(0, second.getColumns().get(0).getRowGroupOrdinal());
  }

