  private static List<SchemaElement> twoColumnSchema() {
    return Arrays.asList(
        new SchemaElement("schema").setNum_children(2),
        new SchemaElement("id")
            .setType(Type.INT32)
            .setRepetition_type(FieldRepetitionType.REQUIRED),
        new SchemaElement("name")
            .setType(Type.BINARY)
            .setRepetition_type(FieldRepetitionType.OPTIONAL));
  }

  private static ColumnMetaData columnMetaData(
      Type type,
      String path,
      long dataPageOffset,
      long numValues,
      long uncompressedSize,
      long compressedSize) {
    return new ColumnMetaData(
        type,
        Collections.singletonList(Encoding.PLAIN),
        Collections.singletonList(path),
        CompressionCodec.UNCOMPRESSED,
        numValues,
        uncompressedSize,
        compressedSize,
        dataPageOffset);
  }

  private static ColumnChunk columnChunk(Type type, String path, String filePath, long dataPageOffset) {
    ColumnChunk columnChunk = new ColumnChunk(dataPageOffset)
        .setMeta_data(columnMetaData(type, path, dataPageOffset, 10L, 100L, 80L));
    if (filePath != null) {
      columnChunk.setFile_path(filePath);
    }
    return columnChunk;
  }
